const GREETINGS_DATA = [
  { country: 'México',         greeting: '¡Qué onda!',       phonetic: 'ke-ON-da'               },
  { country: 'España',         greeting: '¡Buenas!',         phonetic: 'BWEH-nas'               },
  { country: 'Estados Unidos', greeting: "Hey, what's up?",  phonetic: 'hey wuts up'            },
  { country: 'Brasil',         greeting: 'E aí, tudo bem?',  phonetic: 'ee-ah-EE too-doo beng'  },
  { country: 'Argentina',      greeting: '¡Buenas, che!',    phonetic: 'BWEH-nas cheh'          },
  { country: 'Colombia',       greeting: '¡Quiubo, parce!',  phonetic: 'KYU-bo PAR-seh'         },
  { country: 'Reino Unido',    greeting: 'Alright, mate?',   phonetic: 'ol-RAYT mayt'           },
  { country: 'Alemania',       greeting: "Na, wie läuft's?", phonetic: 'nah vee LOYFS'          },
  { country: 'Francia',        greeting: 'Ça roule ?',       phonetic: 'sah ROOL'               },
  { country: 'India',          greeting: 'Kem cho!',         phonetic: 'kem CHO'                },
  { country: 'Japón',          greeting: 'Ossu!',            phonetic: 'OS-su'                  },
  { country: 'Australia',      greeting: "G'day, mate!",     phonetic: 'guh-DAY mayt'           },
];

const searchInput    = document.getElementById('search-input');
const cardsContainer = document.getElementById('cards-container');
const resultsCount   = document.getElementById('results-count');
const clearBtn       = document.getElementById('clear-btn');

function createCard(item) {
  const card = document.createElement('article');
  card.className = 'greeting-card';

  const country = document.createElement('h2');
  country.className = 'card-country';
  country.textContent = item.country;

  const greeting = document.createElement('p');
  greeting.className = 'card-greeting';
  greeting.textContent = item.greeting;

  const phonetic = document.createElement('p');
  phonetic.className = 'card-phonetic';
  phonetic.textContent = item.phonetic;

  card.appendChild(country);
  card.appendChild(greeting);
  card.appendChild(phonetic);

  return card;
}

function renderCards(data) {
  cardsContainer.replaceChildren();
  resultsCount.textContent = data.length + ' país(es) encontrado(s)';

  if (data.length === 0) {
    const empty = document.createElement('p');
    empty.className = 'empty-state';
    empty.textContent = 'No se encontraron resultados.';
    cardsContainer.appendChild(empty);
    return;
  }

  data.forEach(function (item) {
    cardsContainer.appendChild(createCard(item));
  });
}

function filterAndRender() {
  const query = searchInput.value.toLowerCase().trim();
  const filtered = GREETINGS_DATA.filter(function (item) {
    return (
      item.country.toLowerCase().includes(query) ||
      item.greeting.toLowerCase().includes(query) ||
      item.phonetic.toLowerCase().includes(query)
    );
  });
  renderCards(filtered);
}

searchInput.addEventListener('input', filterAndRender);

clearBtn.addEventListener('click', function () {
  searchInput.value = '';
  renderCards(GREETINGS_DATA);
});

renderCards(GREETINGS_DATA);

/* ============================================================
   styles.css — Página de Saludos Internacionales Tsoft (XP-12)
   ============================================================ */

/* ── 1. VARIABLES DE DISEÑO ─────────────────────────────── */
:root {
  --color-primary:         #0A2463;
  --color-primary-light:   #1E3A8A;
  --color-accent:          #E63946;
  --color-bg:              #F8F9FA;
  --color-surface:         #FFFFFF;
  --color-text-primary:    #1A1A2E;
  --color-text-secondary:  #6B7280;
  --color-border:          #E5E7EB;

  --font-family-base:  system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-size-base:    1rem;
  --font-size-sm:      0.875rem;
  --font-size-lg:      1.25rem;
  --font-size-xl:      1.75rem;
  --font-size-hero:    2.25rem;

  --spacing-xs:   0.25rem;
  --spacing-sm:   0.5rem;
  --spacing-md:   1rem;
  --spacing-lg:   1.5rem;
  --spacing-xl:   2rem;
  --spacing-2xl:  3rem;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;

  --shadow-card:       0 2px 8px rgba(0, 0, 0, 0.08);
  --shadow-card-hover: 0 6px 20px rgba(0, 0, 0, 0.14);

  --transition-base: 200ms ease;
}

/* ── 2. RESET MÍNIMO ────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin:  0;
  padding: 0;
}

img {
  max-width: 100%;
  display:   block;
}

ul,
ol {
  list-style: none;
  margin:     0;
  padding:    0;
}

/* ── 3. BODY Y TIPOGRAFÍA BASE ──────────────────────────── */
body {
  font-family:      var(--font-family-base);
  font-size:        var(--font-size-base);
  background-color: var(--color-bg);
  color:            var(--color-text-primary);
  line-height:      1.6;
}

/* ── 4. HEADER ──────────────────────────────────────────── */
#site-header {
  background-color: var(--color-primary);
  color:            #FFFFFF;
  padding:          var(--spacing-md) var(--spacing-xl);
  display:          flex;
  align-items:      center;
  justify-content:  space-between;
  flex-wrap:        wrap;
  gap:              var(--spacing-md);
}

#logo-container {
  display:     flex;
  align-items: center;
  gap:         var(--spacing-sm);
}

#header-text {
  font-size:   var(--font-size-lg);
  font-weight: 700;
  color:       #FFFFFF;
}

#header-subtitle {
  font-size:   var(--font-size-sm);
  font-weight: 400;
  color:       rgba(255, 255, 255, 0.75);
  margin:      0;
}

/* ── 5. SECCIÓN HERO ────────────────────────────────────── */
.hero {
  background:  linear-gradient(135deg, var(--color-primary), var(--color-primary-light));
  color:       #FFFFFF;
  text-align:  center;
  padding:     var(--spacing-2xl) var(--spacing-xl);
}

.hero__title {
  font-size:     var(--font-size-hero);
  font-weight:   800;
  margin-bottom: var(--spacing-sm);
  margin-top:    0;
  color:         var(--color-accent);
}

.hero__subtitle {
  font-size:   var(--font-size-lg);
  font-weight: 400;
  opacity:     0.85;
  margin:      0;
}

/* ── 6. BARRA DE BÚSQUEDA / FILTRO ─────────────────────── */
#search-section {
  max-width: 480px;
  margin:    var(--spacing-xl) auto;
  padding:   0 var(--spacing-md);
}

#search-input {
  width:            100%;
  padding:          var(--spacing-sm) var(--spacing-md);
  font-family:      var(--font-family-base);
  font-size:        var(--font-size-base);
  color:            var(--color-text-primary);
  background-color: var(--color-surface);
  border:           1px solid var(--color-border);
  border-radius:    var(--radius-md);
  outline:          none;
  transition:       border-color var(--transition-base),
                    box-shadow   var(--transition-base);
}

#search-input:focus {
  border-color: var(--color-primary);
  box-shadow:   0 0 0 3px rgba(10, 36, 99, 0.15);
}

#search-input::placeholder {
  color: var(--color-text-secondary);
}

/* ── 7. SECCIÓN DE TARJETAS ─────────────────────────────── */
#greetings-section {
  padding: var(--spacing-xl);
}

/* Contador de resultados y botón limpiar */
#results-count {
  font-size:     var(--font-size-sm);
  color:         var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
  display:       block;
}

#clear-btn {
  display:          inline-flex;
  align-items:      center;
  gap:              var(--spacing-xs);
  padding:          var(--spacing-xs) var(--spacing-sm);
  font-family:      var(--font-family-base);
  font-size:        var(--font-size-sm);
  color:            var(--color-primary);
  background-color: transparent;
  border:           1px solid var(--color-primary);
  border-radius:    var(--radius-sm);
  cursor:           pointer;
  transition:       background-color var(--transition-base),
                    color            var(--transition-base);
  margin-bottom:    var(--spacing-md);
}

#clear-btn:hover {
  background-color: var(--color-primary);
  color:            #FFFFFF;
}

/* Grid de tarjetas */
#greetings-grid {
  display:               grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap:                   var(--spacing-lg);
}

/* ── 8. TARJETA INDIVIDUAL ──────────────────────────────── */
.card {
  background-color: var(--color-surface);
  border:           1px solid var(--color-border);
  border-radius:    var(--radius-lg);
  padding:          var(--spacing-lg);
  box-shadow:       var(--shadow-card);
  transition:       box-shadow   var(--transition-base),
                    transform    var(--transition-base);
  display:          flex;
  flex-direction:   column;
  gap:              var(--spacing-sm);
}

.card:hover {
  box-shadow: var(--shadow-card-hover);
  transform:  translateY(-2px);
}

.card__flag {
  font-size:   var(--font-size-xl);
  line-height: 1;
}

.card__greeting {
  font-size:   var(--font-size-xl);
  font-weight: 700;
  color:       var(--color-accent);
  margin:      0;
}

.card__language {
  font-size:   var(--font-size-sm);
  font-weight: 600;
  color:       var(--color-primary);
  margin:      0;
}

.card__country {
  font-size:  var(--font-size-sm);
  color:      var(--color-text-secondary);
  margin:     0;
}

.card__pronunciation {
  font-size:      var(--font-size-sm);
  color:          var(--color-text-secondary);
  font-style:     italic;
  margin:         0;
  padding-top:    var(--spacing-xs);
  border-top:     1px solid var(--color-border);
  margin-top:     auto;
}

/* ── 9. MENSAJE SIN RESULTADOS ──────────────────────────── */
#no-results-message {
  text-align:  center;
  padding:     var(--spacing-2xl) var(--spacing-xl);
  color:       var(--color-text-secondary);
  font-size:   var(--font-size-lg);
}

/* ── 10. UTILIDAD: OCULTAR ELEMENTOS ────────────────────── */
.hidden {
  display: none !important;
}

/* ── 11. RESPONSIVE — MÓVIL (< 600px) ──────────────────── */
@media (max-width: 599px) {
  #site-header {
    padding:        var(--spacing-sm) var(--spacing-md);
    flex-direction: column;
    align-items:    flex-start;
  }

  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .hero__title {
    font-size: var(--font-size-xl);
  }

  .hero__subtitle {
    font-size: var(--font-size-base);
  }

  #search-section {
    margin:  var(--spacing-lg) auto;
    padding: 0 var(--spacing-sm);
  }

  #greetings-section {
    padding: var(--spacing-md);
  }

  #greetings-grid {
    grid-template-columns: 1fr;
    gap:                   var(--spacing-md);
  }
}
